    if (formaPagamento == FormaPagamento.CARTAO && parcelas > 3) {
        BigDecimal taxaMensal = new BigDecimal("0.0199");
        BigDecimal umMaisTaxa = BigDecimal.ONE.add(taxaMensal);

        BigDecimal potencia = BigDecimal.ONE;
        for (int i = 0; i < parcelas; i++) {
            potencia = potencia.multiply(umMaisTaxa);
        }

        BigDecimal numerador = totalFinal.multiply(potencia).multiply(taxaMensal);
        BigDecimal denominador = potencia.subtract(BigDecimal.ONE);
        return Arredondador.arredondar(numerador.divide(denominador, 10, RoundingMode.HALF_EVEN));
    }
    return Arredondador.arredondar(totalFinal.divide(new BigDecimal(parcelas), 10, RoundingMode.HALF_EVEN));
}

